-- RAW-FINGERPRINT: 56c5a290-1e08-4e04-a099-d5c1c631c3ae

local fingerprint = "56c5a290-1e08-4e04-a099-d5c1c631c3ae"
local payload = ""
local key = "e2821264a17753ed0cb73c35196853c6"

local alphabet =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local lookup = {}
for i = 1, #alphabet do
    lookup[alphabet:sub(i, i)] = i - 1
end

local function decode64(input)
    local output = {}
    local buffer = 0
    local bits = 0

    for i = 1, #input do
        local c = input:sub(i, i)

        if c ~= "=" then
            local value = lookup[c]

            if value ~= nil then
                buffer = buffer * 64 + value
                bits = bits + 6

                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(
                        buffer / (2 ^ bits)
                    ) % 256

                    output[#output + 1] =
                        string.char(byte)

                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end

    return table.concat(output)
end

local function decode_key(hex)
    local result = {}

    for i = 1, #hex, 2 do
        result[#result + 1] =
            string.char(tonumber(hex:sub(i, i + 1), 16))
    end

    return table.concat(result)
end

local encrypted = decode64(payload)
local secret = decode_key(key)
local decoded = {}

for i = 1, #encrypted do
    local a = string.byte(encrypted, i)
    local b = string.byte(
        secret,
        ((i - 1) % #secret) + 1
    )

    decoded[i] = string.char((a ~ b) % 256)
end

local source = table.concat(decoded)

local compiler = loadstring or load
assert(compiler, "Lua compiler unavailable")

local chunk, err = compiler(source)
assert(chunk, err)

return chunk()
